<template><view class="relationship-lines" :style="{width:width+'px',height:height+'px'}"><canvas v-for="tile in tiles" :key="tile.id" :canvas-id="tile.id" :id="tile.id" :style="{position:'absolute',left:tile.left+'px',top:tile.top+'px',width:tile.width+'px',height:tile.height+'px'}" /></view></template>
<script setup>
import {computed,getCurrentInstance,nextTick,onMounted,watch} from 'vue'
const props=defineProps({paths:Array,width:Number,height:Number}),instance=getCurrentInstance(),canvasId='relationship-'+instance.uid
// Split large family diagrams so a 100-generation tree does not exceed native canvas size limits.
const tiles=computed(()=>{const result=[],size=1200;for(let top=0;top<props.height;top+=size)for(let left=0;left<props.width;left+=size)result.push({id:canvasId+'-'+left+'-'+top,left,top,width:Math.min(size,props.width-left),height:Math.min(size,props.height-top)});return result})
function trace(ctx,d){const parts=d.match(/[MHCQ]|-?\d+(?:\.\d+)?/g)||[];let i=0,x=0,y=0;ctx.beginPath();while(i<parts.length){const cmd=parts[i++];if(cmd==='M'){x=+parts[i++];y=+parts[i++];ctx.moveTo(x,y)}else if(cmd==='H'){x=+parts[i++];ctx.lineTo(x,y)}else if(cmd==='C'){const v=parts.slice(i,i+6).map(Number);i+=6;ctx.bezierCurveTo(...v);x=v[4];y=v[5]}else if(cmd==='Q'){const v=parts.slice(i,i+4).map(Number);i+=4;ctx.quadraticCurveTo(...v);x=v[2];y=v[3]}}}
async function draw(){await nextTick();for(const tile of tiles.value){const c=uni.createCanvasContext(tile.id,instance);c.clearRect(0,0,tile.width,tile.height);c.save();c.translate(-tile.left,-tile.top);for(const l of props.paths||[]){const color={parent:'#a05b48',spouse:'#7e302d',sibling:'#7b6b4d'}[l.kind];trace(c,l.d);c.setLineWidth(6);c.setStrokeStyle('#faf8f3');c.setLineDash([]);c.stroke();trace(c,l.d);c.setStrokeStyle(color);c.setLineWidth(l.kind==='spouse'?2.3:l.kind==='sibling'?1.6:1.7);c.setLineDash(l.kind==='sibling'?[5,4]:[]);c.stroke();c.setLineDash([]);c.setFillStyle('#fffdf8');c.setStrokeStyle(color);c.setLineWidth(1);c.beginPath();c.moveTo(l.x-12,l.y-10);c.lineTo(l.x+12,l.y-10);c.arc(l.x+12,l.y,10,-Math.PI/2,Math.PI/2);c.lineTo(l.x-12,l.y+10);c.arc(l.x-12,l.y,10,Math.PI/2,Math.PI*1.5);c.closePath();c.fill();c.stroke();c.setFillStyle(color);c.setFontSize(10);c.setTextAlign('center');c.setTextBaseline('middle');c.fillText(l.label,l.x,l.y)}c.restore();c.draw()}}
watch(()=>[props.paths,props.width,props.height],draw);onMounted(draw)
</script>
